"""Generate a CMakeLists.txt that builds NASM (Chromium's third_party/nasm copy, NASM 3.01) as a host x64 tool.

Source lists and include dirs come from Chromium's nasm_sources.gni / BUILD.gn (nasmlib_sources + nasm_sources,
HAVE_CONFIG_H; config/config.h selects config/msvc.h for MSVC-compatible compilers).
Usage: python -I gen_nasm_cmake.py <nasm-src> <out-dir>
"""
import os
import re
import sys

src, out = sys.argv[1], sys.argv[2]
gni = open(os.path.join(src, 'nasm_sources.gni'), encoding='utf-8').read()


def lst(name):
    m = re.search(name + r' = \[(.*?)\]', gni, re.S)
    return re.findall(r'"([^"]+)"', m.group(1))


files = [f for f in lst('nasmlib_sources') + lst('nasm_sources') if f.endswith('.c')]
for f in files:
    if not os.path.isfile(os.path.join(src, f)):
        sys.exit('missing ' + f)
s = src.replace('\\', '/')
lines = [
    '# Generated by gen_nasm_cmake.py from Chromium third_party/nasm (NASM 3.01) nasm_sources.gni + BUILD.gn.',
    'cmake_minimum_required(VERSION 3.16)',
    'project(nasm LANGUAGES C)',
    'add_executable(nasm',
] + ['    %s/%s' % (s, f) for f in files] + [
    ')',
    'target_include_directories(nasm PRIVATE ' + ' '.join('%s/%s' % (s, d) for d in
                                                         ['.', 'asm', 'disasm', 'include', 'output', 'x86', 'zlib']) + ')',
    'target_compile_definitions(nasm PRIVATE HAVE_CONFIG_H _CRT_SECURE_NO_WARNINGS _CRT_NONSTDC_NO_WARNINGS)',
    '# BUILD.gn win cflags: /wd4005 /wd4018 /wd4028 /wd4132 /wd4146',
    'target_compile_options(nasm PRIVATE /wd4005 /wd4018 /wd4028 /wd4132 /wd4146 -Wno-everything)',
    'install(TARGETS nasm RUNTIME DESTINATION bin)',
]
os.makedirs(out, exist_ok=True)
with open(os.path.join(out, 'CMakeLists.txt'), 'w', encoding='utf-8', newline='\n') as f:
    f.write('\n'.join(lines) + '\n')
print(len(files), 'C files')
